using System;using System.IO;using System.Net;using System.Collections.Generic;using Newtonsoft.Json.Linq;
namespace JonsboStudio {
 static class OnlineCatalog {
  public static JArray BuiltIns(){string path=Path.Combine(AppPaths.Root,"Assets","public-themes.json");return File.Exists(path)?JArray.Parse(File.ReadAllText(path)):new JArray();}
  public static JArray Community(string resolution){string url="https://theme.screen-aio.com/?p=/Do/getThemesByResolution&ext_type="+Uri.EscapeDataString(resolution)+"&page=1&pageSize=48";var json=JObject.Parse(ReadText(url));var result=new JArray();foreach(JObject item in (json["data"] as JArray??new JArray()))result.Add(new JObject{{"id","community-"+(string)item["id"]},{"title",item["title"]},{"width",resolution.Split('×')[0]},{"height",resolution.Split('×')[1]},{"author",(string)item["nickname"]??(string)item["author"]??"Community"},{"thumbnail",item["ico"]},{"sourceUrl","https://theme.screen-aio.com"+(string)item["link"]},{"downloadable",false},{"points",item["pricePoint"]}});return result;}
  static string ReadText(string url){ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;var request=(HttpWebRequest)WebRequest.Create(url);request.Timeout=20000;request.UserAgent="JonsboStudio/1.0";using(var response=request.GetResponse())using(var reader=new StreamReader(response.GetResponseStream()))return reader.ReadToEnd();}
  public static string Download(string id,Action<string> status){JObject item=null;foreach(JObject candidate in BuiltIns())if((string)candidate["id"]==id){item=candidate;break;}if(item==null)throw new InvalidOperationException("This item must be obtained through the official theme store.");var uri=new Uri((string)item["url"]);if(uri.Scheme!="https"||uri.Host!="res.hlinel.com"||!uri.AbsolutePath.StartsWith("/static/upload/other/soft/jsbThemes/",StringComparison.Ordinal))throw new InvalidDataException("Unexpected public theme source.");string path=Path.Combine(AppPaths.Data("Downloads"),id+".zip");if(!File.Exists(path)){string part=path+".part";try{ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;var request=(HttpWebRequest)WebRequest.Create(uri);request.Timeout=30000;using(var response=request.GetResponse())using(var input=response.GetResponseStream())using(var output=File.Create(part)){byte[] buffer=new byte[65536];long total=0;int count;while((count=input.Read(buffer,0,buffer.Length))>0){total+=count;if(total>512L*1024*1024)throw new InvalidDataException("Theme download exceeds 512 MB.");output.Write(buffer,0,count);if(status!=null)status("Downloading "+id+" · "+(total/1048576.0).ToString("0.0")+" MB");}}File.Move(part,path);}finally{if(File.Exists(part))File.Delete(part);}}
   return ThemeRepository.Import(path);
  }
 }
}
